  let privKeyString;
  if (Buffer.isBuffer(privkey)) {
    privKeyString = privkey.toString('hex');
  } else {
    privKeyString = privkey;
  }
  const keys = ecdsa.keyFromPrivate(privKeyString, 'hex');

  // compressed public key
